// Node-RED is authoritative for counter state.
// Input topic: counters/<location>/capacity/command
// Payload examples:
//   {"action":"increment","source":"StopWatch-01"}
//   {"action":"decrement","source":"StopWatch-01"}
//   {"action":"reset"}
//   {"action":"set","value":120}

function locationFromMessage(msg, payload) {
  const parts = String(msg.topic || '').split('/');
  if (parts.length >= 4 && parts[0] === 'counters' && parts[2] === 'capacity') {
    return parts[1];
  }
  return payload?.location || msg.location || 'mccarthys';
}

let payload = msg.payload;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); }
  catch (e) { node.warn('Invalid JSON payload'); return null; }
}

if (!payload || !payload.action) {
  node.warn('Missing action');
  return null;
}

const location = locationFromMessage(msg, payload);
const stateKey = `capacity_counter_${location}`;

let state = flow.get(stateKey);
if (typeof state !== 'number') state = 0;

let action = String(payload.action).trim().toLowerCase();
if (action === '+1' || action === 'plus' || action === 'inc') action = 'increment';
if (action === '-1' || action === 'minus' || action === 'dec') action = 'decrement';

if (action === 'increment') {
  state += 1;
} else if (action === 'decrement') {
  state = Math.max(0, state - 1);
} else if (action === 'reset') {
  state = 0;
} else if (action === 'set') {
  const nextValue = Number(payload.value);
  if (!Number.isFinite(nextValue)) {
    node.warn('Invalid set value');
    return null;
  }
  state = Math.max(0, Math.trunc(nextValue));
} else {
  node.warn(`Unknown action: ${payload.action}`);
  return null;
}

flow.set(stateKey, state);

// Backwards-compatible last active values for dashboard/debug widgets.
flow.set('capacity_counter', state);
flow.set('active_location', location);

node.status({
  fill: "green",
  shape: "dot",
  text: `${location}: ${state}`
});

msg.topic = `counters/${location}/capacity/state`;
msg.payload = {
  value: state,
  location,
  updated_by: 'node_red',
  source: payload.source || payload.updated_by || 'unknown'
};
msg.retain = true;
msg.qos = 1;
return msg;

// Input topic: counters/<location>/capacity/get
const parts = String(msg.topic || '').split('/');
const location = (parts.length >= 4 && parts[0] === 'counters' && parts[2] === 'capacity')
  ? parts[1]
  : msg.location || msg.payload?.location || 'mccarthys';

const stateKey = `capacity_counter_${location}`;
let state = flow.get(stateKey);
if (typeof state !== 'number') {
  state = 0;
  flow.set(stateKey, state);
}

flow.set('capacity_counter', state);
flow.set('active_location', location);

node.status({
  fill: "blue",
  shape: "ring",
  text: `${location}: ${state}`
});

msg.topic = `counters/${location}/capacity/state`;
msg.payload = { value: state, location, updated_by: 'state_request' };
msg.retain = true;
msg.qos = 1;
return msg;

// Remote-RED mobile widgets / iOS shortcuts can emit strings like:
//   action: increment, decrement, reset
// Optional location can be provided as msg.payload.location.
// Default location remains mccarthys.

let action = undefined;
let value = undefined;
let location = 'mccarthys';

if (typeof msg.payload === 'string') {
  action = msg.payload;
} else if (msg.payload && typeof msg.payload === 'object') {
  action = msg.payload.action || msg.payload.Action || msg.payload.command || msg.payload.name;
  value = msg.payload.value;
  location = msg.payload.location || msg.payload.Location || location;
}

if (typeof action === 'string') {
  action = action.trim().toLowerCase();
}

if (action === '+1' || action === 'plus' || action === 'inc') action = 'increment';
if (action === '-1' || action === 'minus' || action === 'dec') action = 'decrement';

if (!['increment', 'decrement', 'reset', 'set'].includes(action)) {
  node.warn('Ignoring Remote-RED action: ' + JSON.stringify(msg.payload));
  return null;
}

msg.topic = `counters/${location}/capacity/command`;
msg.payload = {
  action,
  location,
  source: 'remote_red'
};

if (action === 'set') {
  msg.payload.value = Number(value);
}

return msg;

// Node-RED authoritative state guard.
// Watches counters/<location>/capacity/state without letting devices change the stored count.
// If a non-authoritative publisher overwrites retained state, restore Node-RED's value.

const parts = String(msg.topic || '').split('/');
const location = (parts.length >= 4 && parts[0] === 'counters' && parts[2] === 'capacity')
  ? parts[1]
  : 'mccarthys';

let payload = msg.payload;
if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch (e) {
    const numeric = Number(payload);
    if (Number.isFinite(numeric)) {
      payload = { value: numeric, updated_by: 'external_numeric_state' };
    } else {
      node.warn('Ignoring non-JSON state payload: ' + payload);
      return null;
    }
  }
}

let incomingValue;
if (typeof payload === 'number') {
  incomingValue = payload;
  payload = { value: incomingValue, updated_by: 'external_numeric_state' };
} else if (payload && typeof payload === 'object' && payload.value !== undefined) {
  incomingValue = Number(payload.value);
} else {
  node.warn('Ignoring state payload without value: ' + JSON.stringify(payload));
  return null;
}

if (!Number.isFinite(incomingValue)) {
  node.warn('Ignoring invalid state value: ' + JSON.stringify(payload));
  return null;
}

incomingValue = Math.max(0, Math.trunc(incomingValue));

const stateKey = `capacity_counter_${location}`;
let authoritativeValue = flow.get(stateKey);
if (typeof authoritativeValue !== 'number') {
  authoritativeValue = incomingValue;
  flow.set(stateKey, authoritativeValue);
}

const updatedBy = String(payload.updated_by || payload.source || 'external_state');
const isNodeRedState = updatedBy === 'node_red' || updatedBy === 'state_request';

node.status({
  fill: isNodeRedState ? "green" : "yellow",
  shape: isNodeRedState ? "dot" : "ring",
  text: `${location}: ${authoritativeValue}`
});

const debugMsg = {
  payload: {
    location,
    incoming_value: incomingValue,
    authoritative_value: authoritativeValue,
    updated_by: updatedBy,
    accepted: isNodeRedState
  }
};

if (isNodeRedState || incomingValue === authoritativeValue) {
  return [null, debugMsg];
}

return [
  {
    topic: `counters/${location}/capacity/state`,
    payload: {
      value: authoritativeValue,
      location,
      updated_by: 'node_red',
      corrected_from: updatedBy
    },
    retain: true,
    qos: 1
  },
  debugMsg
];

// Input topic examples:
//   counters/mccarthys/StopWatch-02/battery
//   counters/mccarthys/M5StickS3-01/battery
//
// Legacy accepted:
//   counters/StopWatch-02/battery  -> location defaults to mccarthys
//
// Accepted payload examples:
//   96
//   {"battery":96}
//   {"percent":96}
//   {"value":96}
//   {"battery":96,"device":"StopWatch-02"}

const topicParts = String(msg.topic || '').split('/');

let location = 'mccarthys';
let topicDevice = undefined;

if (topicParts.length >= 4 && topicParts[0] === 'counters' && topicParts[3] === 'battery') {
  location = topicParts[1];
  topicDevice = topicParts[2];
} else if (topicParts.length >= 3 && topicParts[0] === 'counters' && topicParts[2] === 'battery') {
  topicDevice = topicParts[1];
}

let payload = msg.payload;

if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch (e) {
    const numeric = Number(payload);
    if (Number.isFinite(numeric)) {
      payload = { battery: numeric };
    } else {
      node.warn('Ignoring battery payload: ' + payload);
      return null;
    }
  }
}

if (typeof payload === 'number') {
  payload = { battery: payload };
}

if (!payload || typeof payload !== 'object') {
  node.warn('Ignoring invalid battery payload: ' + JSON.stringify(msg.payload));
  return null;
}

let battery = Number(
  payload.battery ??
  payload.percent ??
  payload.value ??
  payload.level ??
  payload.battery_percent
);

if (!Number.isFinite(battery)) {
  node.warn('Battery payload missing numeric battery value: ' + JSON.stringify(payload));
  return null;
}

battery = Math.max(0, Math.min(100, Math.round(battery)));

const device = topicDevice || payload.device || payload.source || 'unknown';

const normalized = {
  battery,
  percent: battery,
  location,
  device,
  source_topic: msg.topic,
  updated_by: device,
  ts: Date.now()
};

let allBatteryStates = flow.get('battery_states_by_location') || {};
if (!allBatteryStates[location]) allBatteryStates[location] = {};
allBatteryStates[location][device] = normalized;
flow.set('battery_states_by_location', allBatteryStates);

// Backwards-compatible last battery views.
flow.set('battery_states', allBatteryStates[location]);
flow.set('capacity_battery', normalized);

node.status({
  fill: battery <= 20 ? "red" : battery <= 50 ? "yellow" : "green",
  shape: "dot",
  text: `${location}/${device}: ${battery}%`
});

return [
  {
    topic: `counters/${location}/${device}/battery/normalized`,
    payload: normalized,
    retain: true,
    qos: 1
  },
  {
    topic: `counters/${location}/capacity/battery/summary`,
    payload: allBatteryStates[location],
    retain: true,
    qos: 1
  },
  {
    payload: normalized
  }
];

// Publishes retained time for ESP32 / StopWatch devices.
// system/time/epoch is the important topic for firmware.

const nowMs = Date.now();
const epoch = Math.floor(nowMs / 1000);
const iso = new Date(nowMs).toISOString();

node.status({
  fill: "blue",
  shape: "dot",
  text: `${epoch}`
});

return [
  {
    topic: 'system/time/epoch',
    payload: epoch,
    retain: true,
    qos: 1
  },
  {
    topic: 'system/time/iso',
    payload: iso,
    retain: true,
    qos: 1
  },
  {
    payload: {
      epoch,
      iso,
      topic_epoch: 'system/time/epoch',
      topic_iso: 'system/time/iso'
    }
  }
];
